import {api,escapeHtml as esc,manilaDate} from './client.js';
import {manilaInput,manilaTimestamp,dateTime} from '../affiliates.js';
import {accountingDateTimePicker,bindAccountingDates} from './accounting-date-picker.js?v=branded-calendars-1';
export function mountMaintenance(root,{owner}){
 if(!owner){root.textContent='Sign in as an owner to manage website maintenance.';return;}
 bindAccountingDates(root);
 let saved=null,busy=false;
 root.innerHTML='<div class="view-heading"><div><span class="eyebrow">Website availability</span><h1>Maintenance</h1><p>Announce planned updates and control when ordering is available.</p></div><button class="button button-secondary" data-maint-refresh>Refresh</button></div><p data-maint-status role="status">Loading maintenance settings…</p><div data-maint-form></div>';
 const status=root.querySelector('[data-maint-status]');
 function paint(){const s=saved.settings,active=saved.status.active;
  root.querySelector('[data-maint-form]').innerHTML=`<section class="panel"><p class="notice"><strong>${active?'Maintenance is active':s.mode==='scheduled'?'Maintenance is scheduled':'Website maintenance is off'}</strong>${active?` · ${saved.status.uploads_paused?'Uploads and payment deadlines are paused.':'Existing order uploads remain available.'}`:s.mode==='scheduled'?` · ${esc(dateTime(s.starts_at))} to ${esc(dateTime(s.ends_at))}`:''}</p><form class="maintenance-form"><label class="field">Maintenance mode<select name="mode"><option value="off" ${s.mode==='off'?'selected':''}>Off — website open</option><option value="manual" ${s.mode==='manual'?'selected':''}>On now — switch off manually</option><option value="scheduled" ${s.mode==='scheduled'?'selected':''}>Scheduled — start and end automatically</option></select></label><div class="field-row">${accountingDateTimePicker('starts','Planned start · Manila',manilaInput(s.starts_at),manilaDate(),{optional:s.mode!=='scheduled'})}${accountingDateTimePicker('ends','Planned end · Manila',manilaInput(s.ends_at),manilaDate(),{optional:s.mode!=='scheduled'})}</div><p class="help-text">Scheduled mode uses these times automatically. In manual mode they announce the plan; maintenance stays on until you turn it off.</p><label class="maintenance-check"><input name="announce" type="checkbox" ${s.announce?'checked':''}>Show a planned-maintenance banner</label><p class="help-text">Use Off with the banner checked to announce an upcoming update without closing the website. The announcement disappears after the planned end.</p><label class="field">Customer message<textarea name="message" required maxlength="400" rows="3">${esc(s.message)}</textarea></label><label class="maintenance-check"><input name="pause_uploads" type="checkbox" ${s.pause_uploads?'checked':''}>Pause payment-proof uploads and their deadlines during maintenance</label><p class="help-text">Recommended for order or payment-system updates. Customers keep their remaining upload time when maintenance ends. Already-expired orders stay expired. Uncheck for visual updates that can safely keep uploads available.</p><p class="help-text">New orders stop during maintenance. Customers can still sign in and view existing orders; your team dashboard stays accessible. Turning maintenance off does not override “Pause new orders” in Shop settings.</p><div class="notice" data-maint-preview></div><p class="form-error" role="alert"></p><button class="button" type="submit">Save maintenance settings</button></form></section>`;
  preview();
 }
 function preview(){const f=root.querySelector('form');if(!f)return;f.querySelectorAll('.accounting-date-picker').forEach(picker=>{picker.dataset.optional=String(f.elements.mode.value!=='scheduled');});root.dataset.dirty='true';f.querySelector('[data-maint-preview]').textContent='Banner preview: '+f.elements.message.value+(f.elements.starts.value?' · '+f.elements.starts.value.replace('T',' ')+(f.elements.ends.value?' to '+f.elements.ends.value.replace('T',' '):'')+' Manila time':'');}
 async function load(){if(busy)return;busy=true;try{saved=await api('maintenance_admin');if(!root.isConnected)return;paint();root.dataset.dirty='false';status.textContent='';}catch(e){status.textContent=e.message;}finally{busy=false;}}
 root.querySelector('[data-maint-refresh]').onclick=()=>{if(root.dataset.dirty==='true'){status.textContent='Save your changes before refreshing, or reopen Maintenance to discard them.';return;}load();};
 root.addEventListener('input',preview);root.addEventListener('change',preview);
 root.addEventListener('submit',async e=>{if(!e.target.matches('.maintenance-form'))return;e.preventDefault();if(busy||!e.target.reportValidity())return;const f=e.target,button=f.querySelector('[type=submit]'),error=f.querySelector('.form-error');busy=true;root.dataset.busy='true';button.disabled=true;error.textContent='';
  try{saved=await api('save_maintenance',{revision:saved.revision,settings:{mode:f.elements.mode.value,announce:f.elements.announce.checked,pause_uploads:f.elements.pause_uploads.checked,message:f.elements.message.value.trim(),starts_at:f.elements.starts.value?manilaTimestamp(f.elements.starts.value):null,ends_at:f.elements.ends.value?manilaTimestamp(f.elements.ends.value):null}});if(!root.isConnected)return;paint();root.dataset.dirty='false';status.textContent='Maintenance settings saved.';}
  catch(e){error.textContent=e.message;}finally{busy=false;root.dataset.busy='false';button.disabled=false;}
 });load();
}
